const cfg = $('A. Config').first().json;

// ---- shared helpers -------------------------------------------------
const TZ = cfg.TZ || 'Asia/Dhaka';
const dfmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
const sfmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
const today = dfmt.format(new Date());
const nowStamp = sfmt.format(new Date());

const addDays = (iso, n) => {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + (parseInt(n, 10) || 0));
  return d.toISOString().slice(0, 10);
};
const daysBetween = (a, b) =>
  Math.round((new Date(b + 'T00:00:00Z') - new Date(a + 'T00:00:00Z')) / 86400000);
const norm = (v) => {
  if (v === null || v === undefined || v === '') return '';
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const d = new Date(s);
  return isNaN(d.getTime()) ? '' : dfmt.format(d);
};
const esc = (s) => String(s === undefined || s === null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const colLetter = (i) => String.fromCharCode(65 + i);

// Tasks sheet layout: A..U. Bot owns A and I..U.
const TASK_COLS = ['Task ID','Task Name','Assignee','Telegram User ID','Duration','Interval',
  'Repeat','Repeat Every','Start Date','End Date','Next Run','Status','Cycle','Last Sent',
  'Completed At','Completed By','Method','Proof URL','Extension Days','Extension Count','DM Message ID'];
// index inside the I..U slice (13 wide)
const IJ = { start:0, end:1, next:2, status:3, cycle:4, lastSent:5, completedAt:6,
             completedBy:7, method:8, proof:9, extDays:10, extCount:11, dmMsgId:12 };

function parseTasks(values) {
  if (!values || values.length < 2) return [];
  const head = (values[0] || []).map((h) => String(h || '').trim());
  const at = (name) => head.indexOf(name);
  for (const c of TASK_COLS) {
    if (at(c) < 0) throw new Error('Tasks sheet is missing the column: ' + c);
  }
  const out = [];
  for (let r = 1; r < values.length; r++) {
    const row = values[r] || [];
    const g = (name) => String(row[at(name)] === undefined ? '' : row[at(name)]).trim();
    const taskName = g('Task Name');
    const userId = g('Telegram User ID');
    if (!taskName && !userId) continue;             // truly blank row
    const raw = [];
    for (let i = 8; i <= 20; i++) raw.push(row[i] === undefined ? '' : row[i]);
    out.push({
      rowNumber: r + 1,
      id: g('Task ID'),
      name: taskName,
      assignee: g('Assignee') || 'Unassigned',
      userId,
      duration: parseInt(g('Duration'), 10) || 0,
      interval: parseInt(g('Interval'), 10) || 0,
      repeat: g('Repeat').toLowerCase() === 'yes',
      repeatEvery: parseInt(g('Repeat Every'), 10) || 0,
      start: norm(g('Start Date')),
      end: norm(g('End Date')),
      next: norm(g('Next Run')),
      status: g('Status'),
      cycle: parseInt(g('Cycle'), 10) || 1,
      extDays: parseInt(g('Extension Days'), 10) || 0,
      extCount: parseInt(g('Extension Count'), 10) || 0,
      dmMsgId: g('DM Message ID'),
      raw,
    });
  }
  return out;
}

// ---------------------------------------------------------------- main
const FINAL_WARNING = String(cfg.FINAL_WARNING || 'true').toLowerCase() !== 'false';
const EXTEND_WINDOW = parseInt(cfg.EXTEND_WINDOW, 10) || 7;

const tasks = parseTasks($input.first().json.values);
const out = [];

for (const t of tasks) {
  if (!t.name || !t.userId || !t.duration || !t.interval) continue;   // incomplete row

  let status = t.status;
  let start = t.start, end = t.end, next = t.next, cycle = t.cycle;
  let taskId = t.id;

  if (status === 'Completed') continue;

  // Revival: an admin pushed End Date into the future on an expired task
  if (status === 'Expired') {
    if (end && today <= end) {
      status = 'Active';
      if (!next || next <= today) next = today;
    } else {
      continue;
    }
  }

  let kind = 'reminder';

  // ---- bootstrap a brand new row ----
  if (!start) {
    start = today;
    end = addDays(start, t.duration);
    next = today;                                   // day-0 announcement
    status = 'Active';
    taskId = taskId || ('T-' + Math.random().toString(36).slice(2, 8).toUpperCase());
    kind = 'assigned';
  }

  // ---- dormant next cycle of a repeating task ----
  if (status === 'Scheduled') {
    if (today < start) continue;
    status = 'Active';
    kind = 'assigned';
  }

  // ---- window closed without completion ----
  if (end && today > end) {
    out.push({ json: {
      action: 'expire', kind: 'expired',
      rowNumber: t.rowNumber, taskId, taskName: t.name, assignee: t.assignee,
      userId: t.userId, cycle, start, end, next, daysLeft: 0,
      today, nowStamp, raw: t.raw, dmMsgId: t.dmMsgId,
      groupText: '\u23F0 <b>Overdue</b>\n\nTask: <b>' + esc(t.name) + '</b>\n'
        + 'Assignee: <a href="tg://user?id=' + t.userId + '">' + esc(t.assignee) + '</a>\n'
        + 'Deadline was ' + end + ' \u2014 not completed.\nRef: ' + taskId,
      dmText: '\u23F0 <b>' + esc(t.name) + '</b> is overdue.\nThe deadline was ' + end
        + '.\n\nYou can still close it, or ask for more time.',
      dmKeyboard: { inline_keyboard: [
        [{ text: '\u2705 Mark as Done', callback_data: 'done:' + taskId }],
        [{ text: '\u23F3 Request extension', callback_data: 'extreq:' + taskId }],
      ]},
    }});
    continue;
  }

  const isFinal = FINAL_WARNING && today === end;
  const isDue = next !== '' && today >= next;
  if (!isDue && !isFinal) continue;

  // Advance from the scheduled date, not from today, so a missed run doesn't
  // shift the cadence; the loop also skips fully-missed pings.
  let newNext = next;
  if (isDue) {
    let guard = 0;
    while (newNext !== '' && newNext <= today && guard++ < 1000) {
      newNext = addDays(newNext, t.interval);
    }
  }

  if (isFinal && kind === 'reminder') kind = 'final';

  const daysLeft = daysBetween(today, end);
  const showExtend = kind === 'final' || daysLeft <= EXTEND_WINDOW;
  const header = kind === 'assigned' ? '\uD83C\uDD95 <b>Task Assigned</b>'
    : kind === 'final' ? '\u26A0\uFE0F <b>Deadline Today</b>'
    : '\uD83D\uDD14 <b>Task Reminder</b>';
  const cyc = cycle > 1 ? ' (cycle ' + cycle + ')' : '';

  const kb = [
    [{ text: '\u2705 Mark as Done', callback_data: 'done:' + taskId },
     { text: '\u23F0 Snooze 2 days', callback_data: 'snooze:' + taskId }],
    [{ text: '\uD83D\uDD01 Not mine', callback_data: 'reassign:' + taskId }],
  ];
  if (showExtend) kb[1].push({ text: '\u23F3 Request extension', callback_data: 'extreq:' + taskId });

  out.push({ json: {
    action: 'send', kind,
    rowNumber: t.rowNumber, taskId, taskName: t.name, assignee: t.assignee,
    userId: t.userId, cycle, start, end, next: newNext, daysLeft,
    today, nowStamp, raw: t.raw, dmMsgId: t.dmMsgId,
    groupText: header + '\n\nTask: <b>' + esc(t.name) + '</b>' + cyc + '\n'
      + 'Assigned to: <a href="tg://user?id=' + t.userId + '">' + esc(t.assignee) + '</a>\n'
      + 'Deadline: ' + end + ' \u2014 ' + daysLeft + ' day(s) left\nRef: ' + taskId,
    dmText: (kind === 'assigned' ? '\uD83C\uDD95 You have been assigned a task.'
           : kind === 'final' ? '\u26A0\uFE0F Deadline is today.'
           : '\uD83D\uDD14 This task is still open.')
      + '\n\n<b>' + esc(t.name) + '</b>\nDeadline: ' + end + ' \u2014 ' + daysLeft + ' day(s) left'
      + '\n\nPress \u2705 when done, or reply to this message with a photo as proof.',
    dmKeyboard: { inline_keyboard: kb },
  }});
}

return out;

