// ---------------------------------------------------------------- main
const evals = $('A. Evaluate tasks').all();
const ins = $input.all();
const ops = [];

for (let i = 0; i < ins.length; i++) {
  const t = (evals[i] || {}).json;
  if (!t) continue;
  const dm = ins[i].json || {};
  const dmOk = dm.ok === true && dm.result;
  const dmMsgId = dmOk ? String(dm.result.message_id) : (t.dmMsgId || '');

  const v = (Array.isArray(t.raw) ? t.raw.slice(0, 13) : []).map((x) => (x === undefined ? '' : x));
  while (v.length < 13) v.push('');

  if (t.action === 'send') {
    v[IJ.start] = t.start;
    v[IJ.end] = t.end;
    v[IJ.next] = t.next;
    v[IJ.status] = 'Active';
    v[IJ.cycle] = t.cycle;
    v[IJ.lastSent] = t.today;
    v[IJ.dmMsgId] = dmMsgId;
  } else {
    v[IJ.status] = 'Expired';
    v[IJ.dmMsgId] = dmMsgId;
  }

  ops.push({ json: { op: 'sheetsBatch', body: { valueInputOption: 'RAW', data: [
    { range: 'Tasks!A' + t.rowNumber, values: [[t.taskId]] },
    { range: 'Tasks!I' + t.rowNumber + ':U' + t.rowNumber, values: [v] },
  ]}}});

  ops.push({ json: { op: 'sheetsAppend', tab: 'Log', body: { values: [[
    t.nowStamp, t.taskId,
    t.action === 'send' ? 'sent:' + t.kind : 'expired',
    'system', t.taskName + ' -> ' + t.assignee,
  ]]}}});

  if (!dmOk) {
    ops.push({ json: { op: 'telegram', method: 'sendMessage', body: {
      chat_id: cfg.GROUP_CHAT_ID, parse_mode: 'HTML',
      text: '\u26A0\uFE0F Could not DM ' + esc(t.assignee) + ' about <b>' + esc(t.taskName)
        + '</b>. They need to send /start to the bot first.',
    }}});
  }
}

return ops;

