// ---------------------------------------------------------------- main
const tasks = parseTasks($input.first().json.values);
const open = [];

for (const t of tasks) {
  if (!t.name) continue;
  if (t.status !== 'Active' && t.status !== 'Expired') continue;
  open.push({
    name: t.name,
    assignee: t.assignee,
    userId: t.userId,
    end: t.end,
    left: t.end ? daysBetween(today, t.end) : null,
    overdue: t.status === 'Expired' || (t.end && today > t.end),
  });
}

if (open.length === 0) {
  return [{ json: { text: '\uD83D\uDCCB <b>Weekly Task Digest</b>\n\n\u2705 Nothing open. All clear.' } }];
}

const byPerson = {};
for (const t of open) (byPerson[t.assignee] = byPerson[t.assignee] || []).push(t);

const lines = ['\uD83D\uDCCB <b>Weekly Task Digest</b>', open.length + ' open task(s)', ''];

const names = Object.keys(byPerson).sort();
for (const person of names) {
  const list = byPerson[person];
  list.sort((a, b) => (a.left === null ? 999 : a.left) - (b.left === null ? 999 : b.left));
  const uid = (list.find((x) => x.userId) || {}).userId;
  lines.push(uid
    ? '<a href="tg://user?id=' + uid + '">' + esc(person) + '</a>'
    : '<b>' + esc(person) + '</b>');
  for (const t of list) {
    const flag = t.overdue ? '\uD83D\uDD34' : (t.left !== null && t.left <= 7) ? '\u26A0\uFE0F' : '\u2022';
    const tail = t.overdue
      ? 'OVERDUE \u2014 was due ' + t.end
      : (t.left + 'd left (' + t.end + ')');
    lines.push('   ' + flag + ' ' + esc(t.name) + ' \u2014 ' + tail);
  }
  lines.push('');
}

const overdue = open.filter((t) => t.overdue).length;
const soon = open.filter((t) => !t.overdue && t.left !== null && t.left <= 7).length;
lines.push('\uD83D\uDD34 ' + overdue + ' overdue \u00B7 \u26A0\uFE0F ' + soon + ' due within 7 days');

return [{ json: { text: lines.join('\n') } }];
